mapper.select:
SELECT u.id, u.username, u.real_name, u.phone, u.dept_id, d.dept_name, u.user_type, u.status, u.last_login_time, u.create_time FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id WHERE u.deleted = 0
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.real_name LIKE CONCAT('%', #{realName}, '%')
AND u.dept_id = #{deptId}
AND u.status = #{status}
ORDER BY u.create_time DESC
